# ============================================================
# PROVIDER COOLDOWN
# ============================================================

CIRCUIT_BREAK_SECONDS = int(
    os.getenv(
        "PROVIDER_COOLDOWN_SECONDS",
        "300"
    )
)


_provider_disabled_until = {}


def provider_available(name):
    """
    Check whether a provider is currently available.
    """

    until = _provider_disabled_until.get(
        name,
        0
    )

    return time.time() >= until


def disable_provider(
    name,
    reason="temporary failure"
):
    """
    Temporarily disable a provider.
    """

    _provider_disabled_until[name] = (
        time.time()
        + CIRCUIT_BREAK_SECONDS
    )

    print(
        f"{name}: TEMPORARILY SKIPPED "
        f"for {CIRCUIT_BREAK_SECONDS}s "
        f"({reason})"
    )


def provider_failure(
    name,
    status_code=None
):
    """
    Disable provider for common temporary/API failures.
    """

    if status_code in (
        401,
        403,
        429
    ):
        disable_provider(
            name,
            f"HTTP {status_code}"
        )


# ============================================================
# SAFE HELPERS
# ============================================================

def clean_answer(value):
    """
    Convert an answer safely into a string.
    """

    if value is None:
        return None

    try:
        value = str(
            value
        ).strip()

    except Exception:
        return None

    return value or None


def request_json(
    response,
    provider
):
    """
    Safely decode JSON.
    """

    try:
        return response.json()

    except Exception as exc:

        print(
            f"{provider}: INVALID JSON:",
            exc
        )

        print(
            f"{provider}: BODY:",
            response.text[:1500]
        )

        return None


