# ============================================================
# GROQ TEXT
# ============================================================

def ask_groq(message):
    """
    PRIMARY TEXT AI.

    All normal text requests go to Groq first.
    """

    if not GROQ_API_KEY:
        print(
            "GROQ: API KEY MISSING"
        )
        return None

    if not message:
        return None

    if not provider_available(
        "GROQ"
    ):
        print(
            "GROQ: TEMPORARILY DISABLED"
        )
        return None

    try:

        print(
            "=" * 50
        )

        print(
            "GROQ PRIMARY TEXT REQUEST"
        )

        print(
            "GROQ MODEL:",
            GROQ_MODEL
        )

        print(
            "GROQ MESSAGE:",
            message[:500]
        )

        print(
            "=" * 50
        )

        response = requests.post(

            GROQ_URL,

            headers={
                "Authorization":
                    f"Bearer {GROQ_API_KEY}",

                "Content-Type":
                    "application/json"
            },

            json={
                "model":
                    GROQ_MODEL,

                "messages": [

                    {
                        "role":
                            "system",

                        "content":
                            GROQ_SYSTEM_PROMPT
                    },

                    {
                        "role":
                            "user",

                        "content":
                            message
                    }
                ],

                "temperature":
                    0.7,

                "max_completion_tokens":
                    4096
            },

            timeout=REQUEST_TIMEOUT
        )


        print(
            "Groq Status:",
            response.status_code
        )


        if response.status_code != 200:

            print(
                "Groq Response:",
                response.text[:2000]
            )

            provider_failure(
                "GROQ",
                response.status_code
            )

            return None


        data = request_json(
            response,
            "Groq"
        )


        if not data:
            return None


        choices = data.get(
            "choices",
            []
        )


        if not choices:
            print(
                "Groq: NO CHOICES"
            )
            return None


        message_data = (
            choices[0]
            .get(
                "message",
                {}
            )
        )


        content = message_data.get(
            "content"
        )


        answer = clean_answer(
            content
        )


        if answer:

            print(
                "Groq response received."
            )

            print(
                "TEXT ROUTE SUCCESS: GROQ"
            )

            return answer


        print(
            "Groq: EMPTY ANSWER"
        )

        return None


    except requests.exceptions.Timeout:

        print(
            "Groq ERROR: timeout."
        )

        return None


    except requests.exceptions.ConnectionError:

        print(
            "Groq ERROR: connection failed."
        )

        return None


    except Exception as exc:

        print(
            "Groq ERROR:",
            exc
        )

        return None


