# GEMINI - SECONDARY TEXT ONLY
# ============================================================

GEMINI_API_KEY = os.getenv(
    "GEMINI_API_KEY"
)


GEMINI_MODEL = os.getenv(
    "GEMINI_MODEL",
    "gemini-3.6-flash"
)


ENABLE_GEMINI = os.getenv(
    "ENABLE_GEMINI",
    "false"
).lower() == "true"


gemini_client = None


if (
    ENABLE_GEMINI
    and GEMINI_API_KEY
    and genai
):

    try:

        gemini_client = genai.Client(
            api_key=GEMINI_API_KEY,

            http_options=HttpOptions(
                timeout=15000
            )
        )

        print(
            "GEMINI CLIENT: READY"
        )

        print(
            "GEMINI MODEL:",
            GEMINI_MODEL
        )

    except Exception as exc:

        print(
            "GEMINI CLIENT ERROR:",
            exc
        )

        gemini_client = None

else:

    print(
        "GEMINI: SKIPPED"
    )


def ask_gemini(message):

    if not ENABLE_GEMINI:
        return None

    if not GEMINI_API_KEY:
        return None

    if gemini_client is None:
        return None

    if not message:
        return None

    if not provider_available(
        "GEMINI"
    ):
        return None

    try:

        print(
            "Trying Gemini TEXT..."
        )

        response = (
            gemini_client
            .models
            .generate_content(

                model=GEMINI_MODEL,

                contents=(
                    GROQ_SYSTEM_PROMPT
                    + "\n\nUSER:\n"
                    + message
                )
            )
        )


        answer = clean_answer(
            getattr(
                response,
                "text",
                None
            )
        )


        if answer:

            print(
                "Gemini TEXT SUCCESS"
            )

            return answer


        return None


    except Exception as exc:

        print(
            "Gemini ERROR:",
            exc
        )

        text = str(
            exc
        )


        if (
            "429" in text
            or
            "RESOURCE_EXHAUSTED" in text
        ):

            disable_provider(
                "GEMINI",
                "quota exceeded"
            )


        return None


