# ============================================================
# IMAGE REQUEST DETECTION
# ============================================================
#
# IMPORTANT:
#
# This is ONLY for recognizing that the user wants
# an image to be generated.
#
# Groq itself does NOT generate the final image.
#
# ============================================================

IMAGE_WORDS = [

    "أنشئ صورة",
    "انشئ صورة",

    "أنشئ لي صورة",
    "انشئ لي صورة",

    "اصنع صورة",
    "اصنع لي صورة",

    "إنشاء صورة",
    "انشاء صورة",

    "ولد صورة",
    "ولّد صورة",

    "ارسم صورة",
    "ارسم لي",

    "صمم صورة",
    "صمم لي صورة",

    "اعمل صورة",
    "اعمل لي صورة",

    "أريد صورة",
    "اريد صورة",

    "أريد أن أرى صورة",
    "اريد ان ارى صورة",

    "generate an image",
    "generate image",

    "create an image",
    "create image",

    "make an image",
    "make image",

    "generate a picture",
    "create a picture",

    "make a picture",
    "draw an image",

    "draw image",
    "draw a picture"
]


def is_image_generation_request(
    message
):
    """
    Detect image-generation requests.

    This function does NOT call Groq as an image generator.
    """

    if not message:
        return False

    text = str(
        message
    ).strip().lower()

    return any(
        word.lower() in text
        for word in IMAGE_WORDS
    )


def get_image_prompt(
    message
):

    if not message:
        return ""

    text = str(
        message
    ).strip()


    prefixes = [

        "أنشئ لي صورة",
        "أنشئ صورة",

        "انشئ لي صورة",
        "انشئ صورة",

        "اصنع لي صورة",
        "اصنع صورة",

        "إنشاء صورة",
        "انشاء صورة",

        "ولد صورة",
        "ولّد صورة",

        "ارسم لي",
        "ارسم صورة",

        "صمم لي صورة",
        "صمم صورة",

        "اعمل لي صورة",
        "اعمل صورة",

        "أريد صورة",
        "اريد صورة",

        "generate an image of",
        "generate image of",

        "create an image of",
        "create image of",

        "make an image of",
        "make image of",

        "generate a picture of",
        "create a picture of",

        "make a picture of",
        "draw an image of"
    ]


    lower = text.lower()


    for prefix in prefixes:

        if lower.startswith(
            prefix.lower()
        ):

            return text[
                len(prefix):
            ].strip()


    return text


