# ============================================================
#
# DO NOT FAKE IMAGE GENERATION.
#
# Groq API is not used here because it does not provide
# a direct image-generation endpoint.
#
# We return a structured result so app.py can handle
# this cleanly later when we connect a real image generator.
#
# ============================================================

def generate_image(
    prompt
):

    prompt = clean_answer(
        prompt
    )


    if not prompt:

        return {

            "answer":
                "اكتب وصف الصورة التي تريد إنشاءها.",

            "imageUrl":
                "",

            "provider":
                None
        }


    print(
        "=" * 60
    )

    print(
        "IMAGE GENERATION REQUEST"
    )

    print(
        "PROMPT:",
        prompt
    )

    print(
        "IMAGE PROVIDER: NONE"
    )

    print(
        "Groq is not an image-generation API."
    )

    print(
        "=" * 60
    )


    return {

        "answer":
            "Groq يستطيع فهم وتحليل الصور، "
            "لكنه لا ينشئ صورة جديدة مباشرةً عبر "
            "Groq API. لذلك لم أرسل طلبًا وهميًا "
            "إلى Groq.",

        "imageUrl":
            "",

        "provider":
            None
    }


# ============================================================
# GROQ VISION
# ============================================================
#
# PRIMARY + ONLY IMAGE UNDERSTANDING PROVIDER
#
# User uploads image
#       ↓
# Base64
#       ↓
# Groq Vision
#       ↓
# Text answer
#
# ============================================================

def ask_groq_image(
    message,
    image_bytes,
    mime_type
):

    if not GROQ_API_KEY:

        print(
            "GROQ VISION: API KEY MISSING"
        )

        return None


    if not image_bytes:

        return None


    if not provider_available(
        "GROQ_VISION"
    ):

        return None


    try:

        print(
            "=" * 60
        )

        print(
            "GROQ PRIMARY VISION REQUEST"
        )

        print(
            "GROQ VISION MODEL:",
            GROQ_VISION_MODEL
        )

        print(
            "IMAGE MIME:",
            mime_type
        )

        print(
            "IMAGE SIZE:",
            len(image_bytes),
            "bytes"
        )

        print(
            "=" * 60
        )


        # ----------------------------------------------------
        # Encode image
        # ----------------------------------------------------

        encoded = base64.b64encode(
            image_bytes
        ).decode(
            "utf-8"
        )


        image_url = (
            f"data:{mime_type};base64,"
            f"{encoded}"
        )


        # ----------------------------------------------------
        # Vision request
        # ----------------------------------------------------

        response = requests.post(

            GROQ_URL,

            headers={
                "Authorization":
                    f"Bearer {GROQ_API_KEY}",

                "Content-Type":
                    "application/json"
            },

            json={

                "model":
                    GROQ_VISION_MODEL,

                "messages": [

                    {
                        "role":
                            "system",

                        "content":
                            GROQ_SYSTEM_PROMPT
                    },

                    {
                        "role":
                            "user",

                        "content": [

                            {
                                "type":
                                    "text",

                                "text":
                                    message
                            },

                            {
                                "type":
                                    "image_url",

                                "image_url": {

                                    "url":
                                        image_url
                                }
                            }
                        ]
                    }
                ],

                "temperature":
                    0.7,

                "max_completion_tokens":
                    4096
            },

            timeout=REQUEST_TIMEOUT
        )


        print(
            "Groq Vision Status:",
            response.status_code
        )


        if response.status_code != 200:

            print(
                "Groq Vision Response:",
                response.text[:2000]
            )

            provider_failure(
                "GROQ_VISION",
                response.status_code
            )

            return None


        data = request_json(
            response,
            "Groq Vision"
        )


        if not data:
            return None


        choices = data.get(
            "choices",
            []
        )


        if not choices:
            return None


        content = (
            choices[0]
            .get(
                "message",
                {}
            )
            .get(
                "content"
            )
        )


        answer = clean_answer(
            content
        )


        if answer:

            print(
                "VISION ROUTE SUCCESS: GROQ"
            )

            return answer


        return None


    except requests.exceptions.Timeout:

        print(
            "Groq Vision ERROR: timeout."
        )

        return None


    except requests.exceptions.ConnectionError:

        print(
            "Groq Vision ERROR: connection failed."
        )

        return None


    except Exception as exc:

        print(
            "Groq Vision ERROR:",
            exc
        )

        return None


# ============================================================
# MAIN TEXT ROUTER
# ============================================================
#
# GROQ IS ALWAYS FIRST.
#
# Secondary providers are TEXT ONLY.
#
# ============================================================

def get_response(
    message,
    conversation_id=None
):

    if not message:

        return (
            "اكتب رسالة أولًا."
        )


    original_message = str(
        message
    ).strip()


    if not original_message:

        return (
            "اكتب رسالة أولًا."
        )


    # ========================================================
    # IMAGE GENERATION REQUEST
    # ========================================================
    #
    # We detect it here so the request does NOT accidentally
    # go to Groq TEXT and return:
    #
    # "I cannot create images..."
    #
    # ========================================================

    if is_image_generation_request(
        original_message
    ):

        prompt = get_image_prompt(
            original_message
        )


        if not prompt:

            return {

                "answer":
                    "اكتب وصف الصورة التي تريد إنشاءها.",

                "imageUrl":
                    "",

                "provider":
                    None
            }


        return generate_image(
            prompt
        )


    # ========================================================
    # IMPORTANT:
    #
    # NO QUICK GREETING RESPONSES HERE.
    #
    # This means:
    #
    # "السلام عليكم"
    #
    # and:
    #
    # "السلام عليكم، أريد منك كتابة برنامج..."
    #
    # both go to Groq.
    #
    # ========================================================


    # ========================================================
    # PRIMARY AI = GROQ
    # ========================================================

    if provider_available(
        "GROQ"
    ):

        answer = ask_groq(
            original_message
        )

        if answer:

            return answer


    print(
        "GROQ failed. "
        "Trying secondary TEXT providers..."
    )


    # ========================================================
    # SECONDARY TEXT PROVIDERS
    # ========================================================

    secondary_routes = [

        (
            "MISTRAL",
            ask_mistral
        ),

        (
            "OPENROUTER",
            ask_openrouter
        ),

        (
            "GEMINI",
            ask_gemini
        ),

        (
            "XAI",
            ask_xai
        ),

        (
            "POLLINATIONS",
            ask_pollinations
        )
    ]


    for name, function in secondary_routes:

        if not provider_available(
            name
        ):

            print(
                f"{name}: SKIPPED "
                "(temporary cooldown)"
            )

            continue


        try:

            answer = function(
                original_message
            )

        except Exception as exc:

            print(
                f"{name} ROUTER ERROR:",
                exc
            )

            answer = None


        if answer:

            print(
                f"SECONDARY TEXT SUCCESS: {name}"
            )

            return answer


        print(
            f"{name} failed. "
            "Trying next provider..."
        )


    # ========================================================
    # ALL PROVIDERS FAILED
    # ========================================================

    return (
        "أنا Ido AI، لكن جميع مزودي الذكاء "
        "الاصطناعي المتاحين فشلوا حاليًا. "
        "تحقق من مفاتيح API والرصيد."
    )


# ============================================================
# MAIN IMAGE ANALYSIS ROUTER
# ============================================================
#
# IMPORTANT:
#
# ONLY GROQ handles uploaded images.
#
# We do NOT send the image to:
#
#     Mistral Vision
#     OpenRouter Vision
#
# because you requested Groq as the primary and only
# image-understanding AI.
#
# ============================================================

def get_image_response(
    message,
    image_bytes,
    mime_type,
    conversation_id=None
):

    if not image_bytes:

        return (
            "لم يتم إرسال صورة صالحة."
        )


    if not mime_type:

        mime_type = "image/jpeg"


    if not mime_type.startswith(
        "image/"
    ):

        return (
            "الملف المرسل ليس صورة صالحة."
        )


    # ========================================================
    # Default question
    # ========================================================

    if (
        not message
        or
        not str(message).strip()
    ):

        message = (
            "حلل هذه الصورة واشرح لي "
            "ما الذي يظهر فيها بالتفصيل."
        )


    message = str(
        message
    ).strip()


    # ========================================================
    # GROQ VISION ONLY
    # ========================================================

    answer = ask_groq_image(

        message,

        image_bytes,

        mime_type
    )


    if answer:

        return answer


    # ========================================================
    # FAILURE
    # ========================================================

    return (
        "تعذر تحليل الصورة باستخدام Groq حاليًا. "
        "تحقق من GROQ_API_KEY، ومن أن الصورة لا "
        "تتجاوز حدود Groq المسموح بها."
    )


# ============================================================
# QUICK RESPONSE
# ============================================================
#
# Kept only for compatibility with old app.py.
#
# IMPORTANT:
#
# It intentionally does NOT return a fixed greeting.
# This prevents:
#
#     "السلام عليكم، أريد منك..."
#
# from being intercepted by a hard-coded response.
#
# ============================================================

def quick_response(
    message
):

    if not message:
        return None

    text = str(
        message
    ).strip()


    if not text:
        return None


    # --------------------------------------------------------
    # Do NOT intercept messages containing a request.
    # --------------------------------------------------------

    request_markers = [

        "أريد",
        "اريد",
        "أريدك",
        "اريدك",

        "كيف",
        "ماذا",
        "لماذا",
        "متى",
        "أين",
        "هل",

        "اعطني",
        "أعطني",

        "اشرح",
        "شرح",

        "اكتب",
        "اكتب لي",

        "ساعدني",
        "مساعدة",

        "صمم",
        "أنشئ",
        "انشئ",
        "اصنع",
        "ارسم",

        "?",
        "؟"
    ]


    lower = text.lower()


    for marker in request_markers:

        if marker.lower() in lower:

            return None


    # --------------------------------------------------------
    # Exact simple greetings only.
    #
    # Even these can be sent to Groq by get_response(),
    # because get_response() no longer calls this function.
    #
    # This function exists only for compatibility.
    # --------------------------------------------------------

    if lower in (
        "hello",
        "hi"
    ):

        return None


    if text in (
        "مرحبا",
        "مرحباً",
        "سلام"
    ):

        return None


    if text in (
        "السلام عليكم",
        "السلام عليكم ورحمة الله وبركاته"
    ):

        return None


    return None


